extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena main.tscn deve istanziarsi correttamente"):
		return

	var player := find_by_name(main, "Player") as CharacterBody2D
	var save_point := find_by_name(main, "SavePoint") as Area2D
	var door := find_by_name(main, "Door")
	var item := find_by_name(main, "Item")

	if not check("elements", player != null and save_point != null and door != null and item != null, "Nella scena principale servono Player, SavePoint, Door e Item"):
		return

	player.global_position = (item as Node2D).global_position
	await wait_physics_frames(4)

	call_if_exists(door, "open")
	await wait_physics_frames(2)

	player.global_position = save_point.global_position
	await wait_physics_frames(4)
	await tap_action("interact")
	await wait_physics_frames(4)

	check("save_feedback", save_point.modulate.g > 0.8, "Il SavePoint deve dare riscontro visivo diventando verde dopo il salvataggio")

	var fresh_main := await instantiate_main_scene()
	var fresh_player := find_by_name(fresh_main, "Player") as CharacterBody2D
	var fresh_door := find_by_name(fresh_main, "Door")
	var save_mgr: Node = fresh_main.get_node_or_null("/root/SaveManager")

	call_if_exists(save_mgr, "load_game", [fresh_player, fresh_main])
	await wait_physics_frames(4)

	var p_dist: float = fresh_player.global_position.distance_to(save_point.global_position)
	check("player_at_savepoint", p_dist < 10.0, "Dopo il ripristino il giocatore deve trovarsi al punto di salvataggio (distanza: %.1f)" % p_dist)

	var is_door_open: bool = bool(get_prop(fresh_door, "is_open", false))
	check("door_still_open", is_door_open == true, "La porta deve essere ancora aperta nel gioco ricaricato")

	var reloaded_item := find_by_name(fresh_main, "Item")
	check("item_not_respawned", reloaded_item == null or reloaded_item.is_queued_for_deletion(), "L'oggetto già raccolto non deve ricomparire al riavvio del livello")

